import{_ as r,a0 as o,w as s,s as n,ao as d,I as p,x as a,a1 as t,A as e}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const P=JSON.parse('{"title":"技術領域小白必不可少的工作技巧和訣竅 | LCTT x X-CMD","titleTemplate":false,"description":"技術領域小白必不可少的工作技巧和訣竅 | LCTT (202304) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"技術領域小白必不可少的工作技巧和訣竅 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"技術領域小白必不可少的工作技巧和訣竅 | LCTT (202304) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202304/20230227.1 ⭐️⭐️ Essential tips and tricks for your first tech job","title":"技術領域小白必不可少的工作技巧和訣竅","tag":"202304","desc":""},"relativePath":"202304/20230227.1 ⭐️⭐️ Essential tips and tricks for your first tech job.md","filePath":"[post].md"}'),u={name:"202304/20230227.1 ⭐️⭐️ Essential tips and tricks for your first tech job.md"};function h(f,l,m,b,x,T){const i=o("Link");return s(),n("div",null,[l[15]||(l[15]=d('<h1 id="技術領域小白必不可少的工作技巧和訣竅" tabindex="-1">技術領域小白必不可少的工作技巧和訣竅 <a class="header-anchor" href="#技術領域小白必不可少的工作技巧和訣竅" aria-label="Permalink to “技術領域小白必不可少的工作技巧和訣竅”">​</a></h1><blockquote><p>開始一份新工作對任何人來説都讓人害怕。下面是如何在你的第一份技術工作的早期階段找到方向。</p></blockquote><p>剛剛入職那幾天確實令人害怕。 我現在依然可以清晰舉出很多例子，例如在第一天上班前的晚上無法入睡，因為不知道第二天將要發生什麼而內心崩潰。對於大多數人來説，開始一份新工作就像踏入未知領域。即使你已是行業的資深人士，不可否認的是，你內心可能還是會對即將發生的事情感到有點害怕。</p><p>可以理解的是，剛入職的時候你的事情很多。你要認識新的人，有新的項目和技術要了解，有文檔要閲讀，有教程要看完，還有沒完沒了的人事培訓和要填的文件。這可能讓你感覺壓力山大，再加上你還面臨着相當大程度的不確定性和未知數，以上種種能引起焦慮。</p><p>促使我寫這篇文章有兩個原因，首先是在我還是學生的時候，大部分討論都圍繞着如何找一份技術工作，卻沒有人談論接下來發生的事情。如何在新角色中脱穎而出？現在回過頭來看，我想我當時認為最困難的事情是得到一份工作，之後發生什麼的一切我都可以自己弄清楚。</p><p>同樣的，在我開始在這個行業工作之後，我發現大部分我看到的與職業相關的內容都是討論如何從一個高級職位升到另一個高級職位。沒有人真正談論在此中間我們要做什麼。實習生和初級工程師呢？他們在早期職業生涯中如何找到方向？</p><p>在擁有了三年全職軟件工程師的經驗（以及之前的幾次實習）之後，我將這段時間的經歷進行了覆盤，並整理出一份我自己在適應新技術職位時使用過的技巧和訣竅清單。我想不只侷限於前面的幾個月，而是優先考慮如何讓這段經歷幫助你實現長期的成功。</p><h3 id="反思現有的流程和文檔" tabindex="-1">反思現有的流程和文檔 <a class="header-anchor" href="#反思現有的流程和文檔" aria-label="Permalink to “反思現有的流程和文檔”">​</a></h3><p>大多數新員工一開始要麼擁有一大堆文檔，要麼根本沒有。你可以將這視為一個機會，而不是被這兩種可能性中的任何一種所淹沒。</p><p>從現有文檔中找到缺口，並想想你可以怎樣為下一位入職的工程師做出這方面的改進。這不僅能顯示你工作的主動性，還表明你致力於改進團隊中的現有流程。</p><p>上述兩種極端情況我都遇到過。我在沒有任何文檔的團隊中工作過，也在一些更新文檔方面很勤快的團隊中工作過。對於前者，你的路徑非常簡單直接，你可以致力於創建那些缺失的文檔。對於後者，你總是可以想辦法改進已有的東西。有時，過多的書面文件也會讓人感到害怕，尤其是對新員工而言。有些事情可能通過其他媒介進行更好地解釋，比如視頻教程或截屏。</p><h3 id="勤問問題" tabindex="-1">勤問問題 <a class="header-anchor" href="#勤問問題" aria-label="Permalink to “勤問問題”">​</a></h3><p>我會建議你在開始一份新工作時研究一下公司是否會為你分配搭檔。這在公司中是相當普遍的做法。工作搭檔的主要作用是在你入職時為你提供幫助。我發現這非常有用，因為這個人能夠針對你所有的問題給出指導，你就不必為了尋找合適的人或部門而四處奔波。</p><p>雖然我鼓勵提問，但在提問之前也有必要做功課，包括：</p><ul><li>做好調查。這包括進行網絡搜索、查看論壇和閲讀現有文檔。使用所有可用的工具。然而，給自己設定時間規劃是很重要的。你必須平衡好盡職調查與牢記手頭項目截止日期和可交付成果。</li><li>説出來。作為母語不是英語的人，我建議你在提問之前大聲把想法説出來。根據我的經驗，我經常發現自己會用一種語言（通常是我的母語）思考但不得不用另一種語言來解釋，而當我在一些困難的問題中掙扎時這一現象尤為突出。有時這頗有挑戰性，因為經過翻譯後的想法可能沒那麼容易理解。</li><li>組織思緒。當你在為某件事而苦苦掙扎時，可能同時有很多不同的想法在你的腦海中翻來覆去。這些想法可能對你來説都挺有道理的，但對於別人來説卻不一定説得通。對此，我建議你坐下來，收集你的想法，寫下來，然後大聲説出來。這一做法可確保當你在解釋自己的思維過程時，你能按照預期進行流暢地表達出來，聽眾也可以緊跟你的思路。</li></ul><p>這種方法稱為橡皮鴨調試法，是開發人員在調試時的常見做法。背後的概念是，有時向第三方解釋你的問題非常有助於你找到解決方案，同時也證明了你出色的溝通技巧。</p><p>尊重別人的時間。即使你在向你的搭檔求助時，也要意識到他們也有自己的日常任務要完成。 我嘗試過的一些事情包括：</p><ul><li>寫下我的問題，然後留出一些時間與我的導師交流，以便與他們交談。</li><li>整理問題而不是反覆尋求幫助，這樣導師可以在他們有空的時候着手解決。</li><li>安排 15-20 分鐘的快速視頻聊天，特別是如果你想共享屏幕，這一方法可以很好地展示你的發現。</li></ul><p>我認為這些方法是更好的選擇，因為這麼做你能得到對方全部的關注，而不是在他們忙着其他事情的時候每隔幾分鐘打擾他們一下。</p><h3 id="深入研究你的項目" tabindex="-1">深入研究你的項目 <a class="header-anchor" href="#深入研究你的項目" aria-label="Permalink to “深入研究你的項目”">​</a></h3><p>即使在擁有出色文檔的團隊中，開始你的技術項目也可能非常艱鉅，因為一個項目涉及多個部分。不過，隨着時間的推移，你將瞭解團隊是如何做事的。但是，通過記下一張實用清單，這包括基本項目設置、測試要求、審查和部署流程、任務跟蹤和文檔，你將迅速搞清楚一切，節省了你的時間和潛在的麻煩。</p><p>如果你開始的項目沒有文檔（我就遇到過這種情況），請看看你能不能找到當前或以前的項目所有者並瞭解基本的項目結構，這包括設置、部署等。</p><ul><li>確定你的團隊在 IDE（集成開發環境）中的偏好。你可以自由使用你喜歡的 IDE，但使用和團隊相同的 IDE 會比較好，尤其是在調試的時候，因為 IDE 的選擇會影響調試。不同的 IDE 提供不同程度的調試支持。</li><li>瞭解如何進行調試。我的意思不僅僅是使用打印語句（不是説這種方法有什麼問題）。充分利用團隊的經驗！</li><li>瞭解測試要求。這可能取決於項目的範圍和團隊的一般慣例，越早弄清楚要求，你在後期推送自己的修改請求時就會越有信心。</li><li>可視化部署過程。這個過程可能因團隊、公司等而異。無論這個過程是非正式或正式，請確保你瞭解自己提交的新代碼是如何被部署至新環境中、部署流水線是什麼樣的、如何安全地部署代碼更改、在構建失敗後可以怎麼做，如何回滾錯誤的更改，以及如何在生產環境中測試你的更改。</li><li>瞭解工單流程。瞭解如何記錄工單以及要求的詳細程度。你會由此發現每個公司各不相同。有的公司希望我們每天提交工單以顯示我們的進度。有的公司可能不需要如此詳細。</li></ul><p>基於我剛才提到的所有內容，我建議你可以在入職頭幾周內做一個有益的、一體化的練習——跟隨模仿另一位工程師並進行結對編碼。這麼做讓你可以端到端地觀察整個流程，從派單給工程師到部署到生產中都清清楚楚。</p><p>如果剛入職幾周時你還沒有機會親身實踐，可能你會感到沮喪。為了解決這個問題，你可以讓你的經理也給你派一些初級的單子。這些通常是一些小任務，例如代碼清理或添加單元測試。不過，它們允許你修補代碼庫，這有助於提高你的理解並給你帶來成就感，這在新工作的初期是非常鼓舞人心的。</p><h3 id="當你遇到困難時尤其要大聲説出來" tabindex="-1">當你遇到困難時尤其要大聲説出來 <a class="header-anchor" href="#當你遇到困難時尤其要大聲説出來" aria-label="Permalink to “當你遇到困難時尤其要大聲説出來”">​</a></h3><p>我想強調一下當你碰到困難時溝通的重要性。遇到困難總是難免的，尤其是在一份新工作的最初幾個月，儘管這可能會令人沮喪，但這正是你的溝通技巧大放異彩的地方。</p><ul><li>讓工作中的阻礙和進步透明化。即使是像權限問題一樣的小事（新員工常常遇到的障礙之一），也要確保你的經理知道。</li><li>如果有些工作耽擱了，不要等到最後一天才向團隊報告。你的項目延遲會推動許多其他事情的發展。對於一些必要的項目延遲請提前告知，以便你的經理可以與相關人員分享這一信息。</li><li>不要因為匆忙而忘記全面測試代碼的更改或為你的代碼的寫文檔等事情。</li></ul><h3 id="獲得技術大局觀" tabindex="-1">獲得技術大局觀 <a class="header-anchor" href="#獲得技術大局觀" aria-label="Permalink to “獲得技術大局觀”">​</a></h3><p>獲得技術大局觀是我個人一直在努力改進的地方，並且我一直在積極改變自己對此的看法。</p><p>當年我開始實習時，我會非常專注於自己想學的東西。我會非常專注於我的項目，但對其他一切完全視而不見。多年後，我意識到對其他或相鄰的項目視而不見可能不是最明智的。</p><p>首先，技術大局觀會影響你對自身工作的理解。我曾經天真地以為，只要我專注於自己的項目就可以成為一名優秀的工程師。但事情並非如此。你應該花時間瞭解其他可能與你的項目有所交互的服務。你無需深入瞭解細節，但建立基本的理解也會大有幫助。</p><p>新員工的一個普遍經歷是與公司其他人脱節，會有這種感覺很正常，尤其是在大公司。我是一個很快就會產生排斥感的人，所以當我剛到 Yelp 時 —— 這是一家比我以前的公司大得多的公司，項目規模也大得多，我優先考慮瞭解大局。我不僅努力建立對我的項目的理解，還認真瞭解了其他相鄰項目。</p><p>在 Yelp 的頭幾周，我與團隊中的其他各位工程師坐下來，請他們給我一個關於我將要做什麼和項目的總體目標的概況。這種方法非常有用，因為我不僅根據工程師的資歷和他們在項目上的工作時間得到了不同程度的解釋，而且還加深了我對我將要從事的工作的理解。我參加這些會議的目的，是希望我對項目掌握的認識讓我能夠向街上的陌生人解釋我所做的事。為此，我還請我的技術主管向我解釋，當用户打開 Yelp 應用程序並搜索內容時，我的工作成果會在什麼時候出現。</p><p>在這種情況下架構圖也很有用，尤其是它能幫助你瞭解不同服務是如何交互的。</p><h3 id="建立期望" tabindex="-1">建立期望 <a class="header-anchor" href="#建立期望" aria-label="Permalink to “建立期望”">​</a></h3><p>在過去很長一段時間裏，我以為自己只需要盡力而為，成為一名優秀的員工就行。只要我有在工作，達成目標，而且沒有人投訴，那就足夠好了，對吧？錯！</p><p>你必須對你的職業有戰略眼光。你不能只是將它外包給人們的一片好心，並希望自己只要達成了目標就能得到想要的結果。</p><ul><li>在你開始新工作的那一刻就建立明確的標準。這因公司而異，因為有些組織有非常明確的措施，而其他組織可能幾乎沒有。如果是後者，我建議你在頭幾周內找你的經理坐下來談談，制定並統一一個標準。</li><li>確保你徹底瞭解公司將如何評估你以及採用什麼方法進行評估。</li></ul><p>我記得在我的第一份全職工作中，我對自己的第一次評估談話一頭霧水。整個談話非常含糊不清，而且我對自己的長處、短處甚至可以如何改進都一無所知。</p><p>起初，我很容易地將一切都歸咎於我的經理，因為作為新員工的我認為這是他們的工作，而不是我的職責。但隨着時間的推移，我意識到，就我的績效評估而言，我不能只是袖手旁觀。你不能只做好工作並期望它就足夠了。你必須積極參與到這些對話中。你必須確保你的努力和貢獻被注意到。為了確保你的工作得到認可，你可以做很多事情，從定期參與技術設計對話到設置團建活動。</p><p>與建立期望相聯繫的還有積極尋求反饋的重要性。不要等到每三、四個月進行一次正式的績效評估時才知道自己的表現如何。積極與你的經理建立反饋循環。雖然這聽起來很可怕，但嘗試定期進行尋求反饋的談話。</p><h3 id="在分佈式團隊中找到方向" tabindex="-1">在分佈式團隊中找到方向 <a class="header-anchor" href="#在分佈式團隊中找到方向" aria-label="Permalink to “在分佈式團隊中找到方向”">​</a></h3><p>在過去兩年中我們的工作場所在不斷變化，如今在遠程和分佈式團隊中工作已成為常態，不再罕見。我列出了一些技巧，幫助你在分佈式團隊中快速找到工作方向：</p><ul><li>建立核心時間並將其設置在你的日曆上。核心時間是你的團隊一致同意的幾個小時，在這段時間裏，大家都明白自己應該在線並能隨時響應。這樣做很方便，因為會議只會安排在這個時間段，讓你在計劃自己一天的工作時更輕鬆。</li><li>注意人們的時區和午餐時間。</li><li>在虛擬世界中，你需要付出更大的努力來維持社交互動，而小小的心意卻可以大大有助於讓工作環境更加友好。</li></ul><p>其中包括：</p><ul><li>開始會議時，互相寒暄並詢問人們週末/一天過得如何。這有助於打破僵局，讓你能夠與團隊成員建立更私人的、超越工作的聯繫。</li><li>建議定期舉行非正式的虛擬聚會，與團隊進行一些隨意的閒聊。</li></ul><h3 id="維持工作生活間的平衡" tabindex="-1">維持工作生活間的平衡 <a class="header-anchor" href="#維持工作生活間的平衡" aria-label="Permalink to “維持工作生活間的平衡”">​</a></h3><p>在你職業生涯剛開始的時候，你很容易認為只要投入很多時間就能成功，特別是考慮到我們全天候待命的“忙碌文化”，以及認為建立生活工作的平衡是在職業生涯下階段才需要考慮的想法。但這些想法與事實相去甚遠，因為工作與生活的平衡不會神奇地發生在你身上。你需要積極和非常勤奮地去找到個人的平衡點。</p><p>沒有工作與生活平衡的可怕之處在於它是慢慢蔓延到你身上的。剛開始是你下班後還在查看電子郵件，然後慢慢地，你開始週末也在工作，一直感到疲憊不堪。</p><p>我列出了一些提示，可以幫助你避免這種情況：</p><ul><li>關閉/暫停通知和電子郵件並將自己設置為離線。</li><li>不要在週末工作。剛開始是你需要在這一個週末工作，但不知不覺間，你會發現自己大部分週末都在工作。不管是什麼工作，它可以等到星期一。</li><li>如果你是待命的工程師，請了解公司的相關政策。一些公司提供金錢補償，而另一些公司可能會以休假代替。利用這個時間。不使用 PTO（帶薪休假）和健康日等福利確實會縮短你的工作壽命。</li></ul><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>毫無疑問，開始一份新工作壓力很大而且很困難。我希望這些方法和技巧會讓你的頭幾個月變得更輕鬆，併為你在新職位上取得巨大成功做好準備。記住，勤溝通，確立職業目標，積極主動，有效地使用公司的工具。做到這些，我相信你會做得很好！</p><hr>',55)),p("p",null,[l[1]||(l[1]=a("via: ",-1)),t(i,{href:"https://opensource.com/article/23/2/your-first-tech-job"},{default:e(()=>[...l[0]||(l[0]=[a("https://opensource.com/article/23/2/your-first-tech-job",-1)])]),_:1})]),p("p",null,[l[6]||(l[6]=a("作者：",-1)),t(i,{href:"https://opensource.com/users/ftaj"},{default:e(()=>[...l[2]||(l[2]=[a("Fatima",-1)])]),_:1}),l[7]||(l[7]=a(" 選題：",-1)),t(i,{href:"https://github.com/lkxed/"},{default:e(()=>[...l[3]||(l[3]=[a("lkxed",-1)])]),_:1}),l[8]||(l[8]=a(" 譯者：",-1)),t(i,{href:"https://github.com/XiaotingHuang22"},{default:e(()=>[...l[4]||(l[4]=[a("XiaotingHuang22",-1)])]),_:1}),l[9]||(l[9]=a(" 校對：",-1)),t(i,{href:"https://github.com/wxy"},{default:e(()=>[...l[5]||(l[5]=[a("wxy",-1)])]),_:1})]),p("p",null,[l[12]||(l[12]=a("本文由 ",-1)),t(i,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...l[10]||(l[10]=[a("LCTT",-1)])]),_:1}),l[13]||(l[13]=a(" 原創編譯，",-1)),t(i,{href:"https://linux.cn/"},{default:e(()=>[...l[11]||(l[11]=[a("Linux中國",-1)])]),_:1}),l[14]||(l[14]=a(" 榮譽推出",-1))])])}const _=r(u,[["render",h]]);export{P as __pageData,_ as default};
